import net.minecraft.SharedConstants; import net.minecraft.server.Bootstrap; import net.minecraft.network.syncher.EntityDataAccessor; import net.minecraft.world.entity.Entity; import java.lang.reflect.*; import java.util.*; import java.util.jar.*;
public class FullPoolProbe { public static void main(String[]a)throws Exception{SharedConstants.tryDetectVersion();Bootstrap.bootStrap(); JarFile j=new JarFile(System.getProperty("jar")); List<String> names=new ArrayList<>(); j.stream().filter(e->e.getName().startsWith("net/minecraft/")&&e.getName().endsWith(".class")&&!e.getName().contains("$" )).forEach(e->names.add(e.getName().substring(0,e.getName().length()-6).replace('/','.'))); Collections.sort(names); for(String n:names) try {Class<?> c=Class.forName(n,false,FullPoolProbe.class.getClassLoader()); if(!Entity.class.isAssignableFrom(c)) continue; Class<?> sup=c.getSuperclass(); int max=-1; try { Class.forName(n,true,FullPoolProbe.class.getClassLoader()); for(Field f:c.getDeclaredFields()) if(EntityDataAccessor.class.isAssignableFrom(f.getType())) {f.setAccessible(true); max=Math.max(max,((EntityDataAccessor<?>)f.get(null)).id());}} catch(Throwable ignored) {} System.out.println(n.replace('.','/')+"\t"+(sup==null?"none":sup.getName().replace('.','/'))+"\t"+(max<0?"none":max)); } catch(Throwable ignored){} }}
